2	
3	export class PatchError extends Error {
4	  constructor(message, index) {
5	    super(message);
6	    this.name = 'PatchError';
7	    this.index = index;
8	  }
9	}
10	
11	const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);
12	const INDEX_RE = /^(?:0|[1-9][0-9]*)$/;
13	const BAD_ESCAPE_RE = /~(?![01])/;
14	
15	export function parsePointer(pointer) {
16	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
17	  if (pointer === '') return [];
18	  if (pointer[0] !== '/') throw new SyntaxError('invalid pointer');
19	  return pointer.slice(1).split('/').map((token) => {
20	    if (BAD_ESCAPE_RE.test(token)) throw new SyntaxError('invalid pointer');
21	    return token.replace(/~[01]/g, (esc) => (esc === '~1' ? '/' : '~'));
22	  });
23	}
24	
25	const isContainer = (v) => v !== null && typeof v === 'object';
26	
27	// Defines an own data property without triggering setters such as __proto__.
28	function setMember(obj, name, value) {
29	  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
30	}
31	
32	// Iterative deep copy: keeps -0 and member order, safe for very deep values.
33	function deepCopy(value) {
34	  if (!isContainer(value)) return value;
35	  const emptyLike = (v) => (Array.isArray(v) ? [] : {});
36	  const root = emptyLike(value);
37	  const stack = [[value, root]];
38	  while (stack.length > 0) {
39	    const [src, dst] = stack.pop();
40	    const isArr = Array.isArray(src);
41	    const keys = isArr ? null : Object.keys(src);
42	    const count = isArr ? src.length : keys.length;
43	    for (let i = 0; i < count; i++) {
44	      const item = isArr ? src[i] : src[keys[i]];
45	      let copy = item;
46	      if (isContainer(item)) {
47	        copy = emptyLike(item);
48	        stack.push([item, copy]);
49	      }
50	      if (isArr) dst.push(copy);
51	      else setMember(dst, keys[i], copy);
52	    }
53	  }
54	  return root;
55	}
56	
57	// Iterative JSON equality: 0 equals -0, object member order is ignored.
58	function jsonEqual(a, b) {
59	  const stack = [[a, b]];
60	  while (stack.length > 0) {
61	    const [x, y] = stack.pop();
62	    if (!isContainer(x) || !isContainer(y)) {
63	      if (x !== y) return false;
64	      continue;
65	    }
66	    if (Array.isArray(x) !== Array.isArray(y)) return false;
67	    if (Array.isArray(x)) {
68	      if (x.length !== y.length) return false;
69	      for (let i = 0; i < x.length; i++) stack.push([x[i], y[i]]);
70	    } else {
71	      const keys = Object.keys(x);
72	      if (keys.length !== Object.keys(y).length) return false;
73	      for (const k of keys) {
74	        if (!Object.hasOwn(y, k)) return false;
75	        stack.push([x[k], y[k]]);
76	      }
77	    }
78	  }
79	  return true;
80	}
