84	// Returns the child of `node` named by `token`, or throws a StepError reason.
85	function step(node, token, notFound) {
86	  if (Array.isArray(node)) {
87	    if (token !== '-' && !INDEX_RE.test(token)) throw new StepError('bad index');
88	    if (token !== '-' && Number(token) < node.length) return node[Number(token)];
89	    throw new StepError(notFound);
90	  }
91	  if (isContainer(node) && Object.hasOwn(node, token)) return node[token];
92	  throw new StepError(notFound);
93	}
