105	function addAt(doc, tokens, value) {
106	  if (tokens.length === 0) return value;
107	  const parent = parentOf(doc, tokens, 'path not found');
108	  const last = tokens[tokens.length - 1];
109	  if (Array.isArray(parent)) {
110	    if (last === '-') {
111	      parent.push(value);
112	    } else if (!INDEX_RE.test(last)) {
113	      throw new StepError('bad index');
114	    } else if (Number(last) > parent.length) {
115	      throw new StepError('path not found');
116	    } else {
117	      parent.splice(Number(last), 0, value);
118	    }
119	  } else if (isContainer(parent)) {
120	    setMember(parent, last, value);
121	  } else {
122	    throw new StepError('path not found');
123	  }
124	  return doc;
125	}
