127	// Removes the value at non-empty `tokens`, returning it.
128	function removeAt(doc, tokens, notFound) {
129	  const parent = parentOf(doc, tokens, notFound);
130	  const last = tokens[tokens.length - 1];
131	  const value = step(parent, last, notFound);
132	  if (Array.isArray(parent)) parent.splice(Number(last), 1);
133	  else delete parent[last];
134	  return value;
135	}
