137	function replaceAt(doc, tokens, value) {
138	  if (tokens.length === 0) return value;
139	  const parent = parentOf(doc, tokens, 'path not found');
140	  const last = tokens[tokens.length - 1];
141	  step(parent, last, 'path not found');
142	  if (Array.isArray(parent)) parent[Number(last)] = value;
143	  else setMember(parent, last, value);
