159	// Returns the form-rule reason for `op`, or a normalized operation.
160	function checkForm(op) {
161	  if (op === null || typeof op !== 'object' || Array.isArray(op)) return 'not an object';
162	  const has = (name) => Object.hasOwn(op, name);
163	  if (!has('op') || !OPS.has(op.op)) return 'bad op';
164	  const path = has('path') ? tryParse(op.path) : null;
165	  if (path === null) return 'bad path';
166	  const kind = op.op;
167	  let from = null;
168	  if (kind === 'move' || kind === 'copy') {
169	    from = has('from') ? tryParse(op.from) : null;
170	    if (from === null) return 'bad from';
171	  }
172	  if ((kind === 'add' || kind === 'replace' || kind === 'test') && !has('value')) return 'missing value';
173	  if (kind === 'remove' && path.length === 0) return 'cannot remove root';
174	  if (kind === 'move' && isProperPrefix(from, path)) return 'cannot move into own child';
175	  return { kind, path, from, value: op.value };
176	}
177	
178	function applyOne(doc, { kind, path, from, value }) {
179	  switch (kind) {
180	    case 'add':
181	      return addAt(doc, path, deepCopy(value));
182	    case 'remove':
183	      removeAt(doc, path, 'path not found');
184	      return doc;
185	    case 'replace':
186	      return replaceAt(doc, path, deepCopy(value));
187	    case 'move': {
188	      follow(doc, from, 'from not found');
189	      if (sameTokens(from, path)) return doc;
190	      const moved = removeAt(doc, from, 'from not found');
191	      return addAt(doc, path, moved);
192	    }
193	    case 'copy':
194	      return addAt(doc, path, deepCopy(follow(doc, from, 'from not found')));
195	    case 'test':
196	      if (!jsonEqual(follow(doc, path, 'path not found'), value)) throw new StepError('test failed');
197	      return doc;
198	  }
199	}
