201	export function applyPatch(doc, patch) {
202	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
203	  const ops = [];
204	  for (let i = 0; i < patch.length; i++) {
205	    const form = checkForm(patch[i]);
206	    if (typeof form === 'string') throw new PatchError(`operation ${i}: ${form}`, i);
207	    ops.push(form);
208	  }
209	  let result = deepCopy(doc);
210	  for (let i = 0; i < ops.length; i++) {
211	    try {
212	      result = applyOne(result, ops[i]);
213	    } catch (err) {
214	      if (err instanceof StepError) throw new PatchError(`operation ${i}: ${err.message}`, i);
215	      throw err;
216	    }
