    const doc = mixedDoc();
    const patch = mixedPatch();
    const r = applyPatch(doc, patch);
    const inputs = new Set([...collectObjects(doc), ...collectObjects(patch)]);
    const shared = [...collectObjects(r)].filter((o) => inputs.has(o));
