    const r = applyPatch({ b: 0 }, [{ op: 'add', path: '/__proto__', value: 1 }]);
    assert.deepStrictEqual(Object.keys(r), ['b', '__proto__']);
    assert.equal(Object.getPrototypeOf(r), Object.prototype);
  });

